local PkgImage = require("pkg_image")
local B,W=15,0
local pages={"行情","指标","快讯"}
local function quote(ctx) local r=ctx.package:open_text("quote.tsv"); if not r then return nil end; r:read_line(); local line=r:read_line(); r:close(); local f={}; for v in (line.."\t"):gmatch("([^\t]*)\t") do f[#f+1]=v end; local trend={}; for v in (f[17] or ""):gmatch("[^,]+") do trend[#trend+1]=tonumber(v) end; return {price=f[6],change=f[7],pct=f[8],open=f[9],high=f[10],low=f[11],prev=f[12],volume=f[13],turnover=f[14],pe=f[15],cap=f[16],trend=trend,date=f[3],time=f[4]} end
local function header(g,s) g:clear(W); PkgImage.draw(g, "brand_logo", 24, 18); g:text(362,32,"3690.HK",{color=B}); g:line(24,78,456,78,{color=B}); for i,v in ipairs(pages) do local x=24+(i-1)*144; g:text(x+34,102,v,{color=B}); if s.page==i then g:line(x+18,132,x+102,132,{color=B}); g:line(x+18,135,x+102,135,{color=B}) end end end
local function chart(g,p) local x,y,w,h=24,378,432,238; for i=1,3 do g:line(x,y+i*54,x+w,y+i*54,{color=B}) end; local min,max=p[1],p[1]; for _,v in ipairs(p) do min=math.min(min,v); max=math.max(max,v) end; local span=math.max(.1,max-min); for i=2,#p do local x1=x+(i-2)*w/(#p-1); local x2=x+(i-1)*w/(#p-1); local y1=y+h-(p[i-1]-min)*h/span; local y2=y+h-(p[i]-min)*h/span; g:line(math.floor(x1),math.floor(y1),math.floor(x2),math.floor(y2),{color=B}) end; g:text(24,630,"09:30",{color=B}); g:text(216,630,"12:00",{color=B}); g:text(406,630,"16:00",{color=B}) end
local function market(g,s,q) header(g,s); g:text(24,164,"HKD",{color=B}); g:text(24,208,q.price,{color=B}); g:text(274,208,"+"..q.change.."  +"..q.pct.."%",{color=B}); g:text(24,252,q.date.."  "..q.time,{color=B}); g:line(24,292,456,292,{color=B}); g:text(24,320,"当日走势",{color=B}); chart(g,q.trend); g:line(24,672,456,672,{color=B}); g:text(24,696,"开 "..q.open.."   高 "..q.high,{color=B}); g:text(24,728,"低 "..q.low.."   昨收 "..q.prev,{color=B}) end
local function metrics(g,s,q) header(g,s); g:text(24,158,"关键指标",{color=B}); local rows={{"今开",q.open,"较昨收 +0.59%"},{"最高",q.high,"日内高点"},{"最低",q.low,"日内低点"},{"成交量",q.volume,"成交额 "..q.turnover},{"市盈率",q.pe,"PE (TTM)"},{"总市值",q.cap,"港元"}}; for i,v in ipairs(rows) do local y=204+(i-1)*86; g:text(44,y,v[1],{color=B}); g:text(174,y,v[2],{color=B}); g:text(324,y,v[3],{color=B}); g:line(44,y+48,456,y+48,{color=B}); if i==1 then g:rect(24,y-6,5,52,{fill=true,color=B}) end end end
local function news(g,s) header(g,s); g:text(24,158,"公司快讯",{color=B}); PkgImage.draw(g, "feature_scene", 120, 194); local rows={{"16:08","3690.HK 收于 104.60 港元"},{"14:32","午后成交活跃，价格震荡上行"},{"11:18","股价站上当日均价线"},{"09:30","开盘报 102.80 港元"}}; for i,v in ipairs(rows) do local y=382+(i-1)*82; g:text(24,y,v[1],{color=B}); g:text(104,y,v[2],{color=B}); g:line(104,y+46,456,y+46,{color=B}) end; g:line(24,718,456,718,{color=B}); g:text(54,738,"走势、指标、快讯触屏切换",{color=B}) end
function on_load(ctx) if not ctx.state.stock then ctx.state.stock={page=1,q=quote(ctx)} end; ctx:set_tick(0) end
function on_draw(ctx,g) require("pkg_image").bind(ctx); local s=ctx.state.stock; if s.page==1 then market(g,s,s.q) elseif s.page==2 then metrics(g,s,s.q) else news(g,s) end end
function on_input(ctx,ev) if not (ev.type == "pointer" and ev.phase == "up") then return false end; local s=ctx.state.stock; if ev.gesture=="swipe_left" then s.page=s.page%3+1 elseif ev.gesture=="swipe_right" then s.page=(s.page+1)%3+1 elseif ev.gesture=="tap" and ev.y>=88 and ev.y<=140 then s.page=math.max(1,math.min(3,math.floor((ev.x-24)/144)+1)) else return false end; ctx:invalidate(); return true end
